const cssv = n => getComputedStyle(document.documentElement).getPropertyValue(n).trim() || '#888';
const letters = s => String(s).toLowerCase().replace(/[^a-z]/g, '');
const ABC = 'abcdefghijklmnopqrstuvwxyz';
function swipe(el, fn){ let sx = 0, sy = 0; el.addEventListener('touchstart', e => { const t = e.touches[0]; sx = t.clientX; sy = t.clientY; }, {passive:true});
  el.addEventListener('touchend', e => { const t = e.changedTouches[0], dx = t.clientX - sx, dy = t.clientY - sy; if (Math.max(Math.abs(dx), Math.abs(dy)) < 24) return; fn(Math.abs(dx) > Math.abs(dy) ? (dx > 0 ? 'r' : 'l') : (dy > 0 ? 'd' : 'u')); }, {passive:true}); }
function endScreen(title, score, best, extra, again){
  $('#stage').innerHTML = `<div class="mode-tag">${title}</div><div class="word">${score}</div><div class="hint">${extra}<br>Best for ${esc(lesson)}: ${best}</div><div class="row"><button class="big gold" id="again">Play again</button></div>`;
  $('#again').onclick = again;
}

// ===== Snake: eat the letters of the word in the right order =====
const SG = 14;
let sn = null;
function snNew(){ return { lesson, deck:shuffle(words()), score:0, hearts:3, phase:'intro', w:null, need:'', got:'', body:[], dir:'r', nextDir:'r', food:[], speed:230, done:0, msg:'' }; }
function snWord(){ if (!sn.deck.length) sn.deck = shuffle(words()); sn.w = sn.deck.pop(); sn.need = letters(sn.w[0]); sn.got = ''; snFood(); }
function snFree(){ const taken = new Set(sn.body.map(c => c.join(',')).concat(sn.food.map(f => f.y + ',' + f.x))); let y, x, n = 0; do { y = Math.floor(Math.random()*SG); x = Math.floor(Math.random()*SG); n++; } while (taken.has(y + ',' + x) && n < 500); return [y, x]; }
function snFood(){ sn.food = []; const want = sn.need[sn.got.length]; const decoys = shuffle(ABC.replace(want, '').split('')).slice(0, 3);
  [want].concat(decoys).forEach(l => { const [y, x] = snFree(); sn.food.push({ y, x, l }); }); }
function snStart(){ sn.body = [[7,4],[7,3],[7,2]]; sn.dir = sn.nextDir = 'r'; }
function snake(){
  if (!sn || sn.lesson !== lesson) sn = snNew();
  const best = load('snake:' + lesson, 0), S = $('#stage');
  if (sn.phase === 'over'){ clearInterval(loop.iv); if (sn.score > best) save('snake:' + lesson, sn.score);
    return endScreen('GAME OVER', sn.score, Math.max(best, sn.score), `${sn.done} word${sn.done === 1 ? '' : 's'} spelled. ${esc(sn.msg)}`, () => { sn = null; snake(); }); }
  if (sn.phase === 'intro'){
    S.innerHTML = `<p class="how">Snake (solo): read the meaning, then steer the snake to eat the letters of the word <b>in the right order</b>. A wrong letter or hitting a wall costs a heart ♥. Every word makes the snake longer and faster.</p>
      <div class="word" style="font-size:44px">Ready, snake?</div><div class="hint">Arrow keys or WASD on a computer · swipe or the arrow buttons on a phone<br>Best for ${esc(lesson)}: ${best}</div><div class="row"><button class="big gold" id="go">Start</button></div>`;
    $('#go').onclick = () => { sn.phase = 'play'; snStart(); snWord(); snake(); }; return;
  }
  const prog = sn.need.split('').map((c, i) => i < sn.got.length ? c : '_').join(' ');
  S.innerHTML = `<p class="how">Eat the letters in order. Wrong letter or crash = −1 ♥.</p>
    <div class="stats"><span>Score: ${sn.score}</span><span>Words: ${sn.done}</span><span class="hearts" aria-label="${sn.hearts} hearts left">${'♥'.repeat(sn.hearts)}${'♡'.repeat(3 - sn.hearts)}</span><span>Best: ${best}</span></div>
    <div class="arc"><div><canvas id="sc" width="420" height="420" aria-label="Snake board"></canvas>
    <div class="dpad" aria-label="Direction buttons"><button class="u" data-d="u" aria-label="Up">▲</button><button class="l" data-d="l" aria-label="Left">◀</button><button class="d" data-d="d" aria-label="Down">▼</button><button class="r" data-d="r" aria-label="Right">▶</button></div></div>
    <div class="panel top"><div class="mode-tag">SPELL THE WORD</div><div class="def">${esc(sn.w[1])}</div><div class="prog" id="sp" aria-live="polite">${prog}</div><div class="hint" id="smsg">${esc(sn.msg)}</div></div></div>`;
  const cv = $('#sc'), cx = cv.getContext('2d'), cs = cv.width / SG;
  const turn = d => { const opp = {u:'d', d:'u', l:'r', r:'l'}; if (d !== opp[sn.dir]) sn.nextDir = d; };
  S.querySelectorAll('.dpad button').forEach(b => b.onclick = () => turn(b.dataset.d));
  swipe(cv, turn); sn.turn = turn;
  const draw = () => {
    const bg = cssv('--card'), line = cssv('--line'), fg = cssv('--fg');
    cx.fillStyle = bg; cx.fillRect(0, 0, cv.width, cv.height);
    cx.strokeStyle = line; cx.lineWidth = 1; for (let i = 1; i < SG; i++){ cx.beginPath(); cx.moveTo(i*cs, 0); cx.lineTo(i*cs, cv.height); cx.moveTo(0, i*cs); cx.lineTo(cv.width, i*cs); cx.stroke(); }
    sn.food.forEach(f => { cx.fillStyle = '#C9A227'; cx.beginPath(); cx.arc(f.x*cs + cs/2, f.y*cs + cs/2, cs*0.46, 0, 7); cx.fill();
      cx.fillStyle = '#14213D'; cx.font = `800 ${Math.round(cs*0.62)}px Manrope, Calibri, sans-serif`; cx.textAlign = 'center'; cx.textBaseline = 'middle'; cx.fillText(f.l, f.x*cs + cs/2, f.y*cs + cs/2 + 1); });
    sn.body.forEach(([y, x], i) => { cx.fillStyle = i ? '#2F8F6B' : '#1E6B4F'; const p = 2; cx.fillRect(x*cs + p, y*cs + p, cs - 2*p, cs - 2*p); });
    const [hy, hx] = sn.body[0]; cx.fillStyle = '#FFFFFF'; cx.beginPath(); cx.arc(hx*cs + cs/2, hy*cs + cs/2, cs*0.12, 0, 7); cx.fill(); void fg;
  };
  const tick = () => {
    if (mode !== 'snake' || !sn || sn.phase !== 'play'){ clearInterval(loop.iv); return; }
    sn.dir = sn.nextDir; const [hy, hx] = sn.body[0]; const d = {u:[-1,0], d:[1,0], l:[0,-1], r:[0,1]}[sn.dir]; const ny = hy + d[0], nx = hx + d[1];
    const hurt = m => { sn.hearts--; sn.msg = m; if (sn.hearts <= 0){ sn.phase = 'over'; clearInterval(loop.iv); return snake(); } snStart(); snFood(); snake(); };
    if (ny < 0 || nx < 0 || ny >= SG || nx >= SG || sn.body.some(([y, x]) => y === ny && x === nx)) return hurt('Ouch! You crashed.');
    sn.body.unshift([ny, nx]);
    const f = sn.food.find(o => o.y === ny && o.x === nx);
    if (f){
      if (f.l === sn.need[sn.got.length]){ sn.got += f.l; sn.score += 2;
        if (sn.got === sn.need){ sn.done++; sn.score += 10 + sn.need.length; sn.msg = `Yes: “${sn.w[0]}”!`; sn.speed = Math.max(110, sn.speed - 12); snWord(); return snake(); }
        snFood(); const p = $('#sp'); if (p) p.textContent = sn.need.split('').map((c, i) => i < sn.got.length ? c : '_').join(' ');
      } else { sn.body.shift(); return hurt(`Wrong letter: the next letter was “${sn.need[sn.got.length]}”.`); }
    } else sn.body.pop();
    draw();
  };
  draw(); clearInterval(loop.iv); loop.iv = setInterval(tick, sn.speed);
}

// ===== Tower: answer to get a wide block, then drop it on the tower =====
let tw = null;
function twNew(){ return { lesson, deck:shuffle(words()), phase:'intro', floors:[{x:90, w:240}], cur:null, q:null, opts:null, score:0, perfect:0, msg:'', speed:2.2 }; }
function tower(){
  if (!tw || tw.lesson !== lesson) tw = twNew();
  const best = load('tower:' + lesson, 0), S = $('#stage');
  if (tw.phase === 'over'){ cancelAnimationFrame(loop.raf); if (tw.score > best) save('tower:' + lesson, tw.score);
    return endScreen('THE TOWER FELL!', tw.score, Math.max(best, tw.score), `${tw.floors.length - 1} floors · ${tw.perfect} perfect drops. ${esc(tw.msg)}`, () => { tw = null; tower(); }); }
  if (tw.phase === 'intro'){
    S.innerHTML = `<p class="how">Tower (solo): answer a question to get your next block. A right answer gives a full-size block; a wrong answer gives a small one. Then tap to drop it on the tower. Anything that hangs over the edge falls off. Miss completely and the tower falls!</p>
      <div class="word" style="font-size:44px">How high can you build?</div><div class="hint">Tap the tower, press Space, or press Drop<br>Best for ${esc(lesson)}: ${best}</div><div class="row"><button class="big gold" id="go">Start building</button></div>`;
    $('#go').onclick = () => { tw.phase = 'ask'; twAsk(); tower(); }; return;
  }
  const top = tw.floors[tw.floors.length - 1];
  const panel = tw.phase === 'ask'
    ? `<div class="mode-tag">ANSWER FOR A BIG BLOCK</div><div class="def">${esc(tw.q[1])}</div><div class="opts" style="grid-template-columns:1fr 1fr">${tw.opts.map((o, i) => `<button data-i="${i}">${esc(o[0])}</button>`).join('')}</div><div class="hint" style="margin-top:12px">${esc(tw.msg)}</div>`
    : `<div class="mode-tag">DROP IT!</div><div class="hint">${esc(tw.msg)}</div><div class="row"><button class="big gold" id="drop">Drop (Space)</button></div>`;
  S.innerHTML = `<p class="how">Answer, then drop the block exactly on top. Perfect drop = +5 bonus.</p>
    <div class="stats"><span>Floors: ${tw.floors.length - 1}</span><span>Score: ${tw.score}</span><span>Perfect: ${tw.perfect}</span><span>Best: ${best}</span></div>
    <div class="arc"><canvas id="tc" width="420" height="480" aria-label="Tower"></canvas><div class="panel top">${panel}</div></div>`;
  const cv = $('#tc'), cx = cv.getContext('2d'), H = 26, base = cv.height - 30;
  const shift = () => Math.max(0, (tw.floors.length - 12) * H);
  const draw = () => {
    cx.fillStyle = cssv('--card'); cx.fillRect(0, 0, cv.width, cv.height);
    cx.fillStyle = cssv('--line'); cx.fillRect(0, base + shift() + H, cv.width, 40);
    const cols = ['#14213D', '#2E6DA4', '#2F8F6B', '#C9A227', '#B4533C', '#7A5BA8'];
    tw.floors.forEach((f, i) => { const y = base - i*H + shift(); if (y < -H || y > cv.height) return; cx.fillStyle = cols[i % cols.length]; cx.fillRect(f.x, y, f.w, H - 3); });
    if (tw.cur){ const y = base - tw.floors.length*H + shift(); cx.fillStyle = '#E7CF7A'; cx.fillRect(tw.cur.x, y, tw.cur.w, H - 3); cx.strokeStyle = '#C9A227'; cx.lineWidth = 2; cx.strokeRect(tw.cur.x + 1, y + 1, tw.cur.w - 2, H - 5); }
  };
  const drop = () => {
    if (tw.phase !== 'swing') return; cancelAnimationFrame(loop.raf);
    const c = tw.cur, l = Math.max(c.x, top.x), r = Math.min(c.x + c.w, top.x + top.w), ov = r - l;
    if (ov <= 0){ tw.phase = 'over'; tw.msg = 'You missed the tower.'; return tower(); }
    let nf = { x:l, w:ov };
    if (Math.abs(c.x - top.x) <= 4 && c.w >= top.w - 1){ nf = { x:top.x, w:Math.min(c.w, top.w) }; tw.perfect++; tw.score += 5; tw.msg = 'PERFECT drop! +5'; }
    else tw.msg = ov < c.w ? 'Some of the block fell off.' : 'Nice!';
    tw.floors.push(nf); tw.score += 10; tw.cur = null; tw.speed = Math.min(6, tw.speed + 0.18);
    if (nf.w < 8){ tw.phase = 'over'; tw.msg = 'The block was too small to stand on.'; return tower(); }
    tw.phase = 'ask'; twAsk(); tower();
  };
  if (tw.phase === 'ask'){
    draw();
    S.querySelectorAll('.opts button').forEach(b => b.onclick = () => {
      const o = tw.opts[+b.dataset.i], ok = o === tw.q;
      const w = ok ? Math.min(240, top.w + 24) : Math.max(24, Math.round(top.w * 0.55));
      tw.msg = ok ? 'Correct: a big block!' : `Not quite: “${tw.q[0]}”. Small block…`;
      if (ok) tw.score += 3;
      tw.cur = { x:0, w, v:tw.speed }; tw.phase = 'swing'; tower();
    });
    return;
  }
  $('#drop').onclick = drop; cv.onclick = drop; tw.drop = drop;
  cancelAnimationFrame(loop.raf);
  const step = () => { if (mode !== 'tower' || !tw || tw.phase !== 'swing') return;
    const c = tw.cur; c.x += c.v; if (c.x <= 0){ c.x = 0; c.v = Math.abs(c.v); } if (c.x + c.w >= cv.width){ c.x = cv.width - c.w; c.v = -Math.abs(c.v); }
    draw(); loop.raf = requestAnimationFrame(step); };
  loop.raf = requestAnimationFrame(step);
}
function twAsk(){ if (!tw.deck.length) tw.deck = shuffle(words()); tw.q = tw.deck.pop(); tw.opts = mcq(tw.q); }

// ===== 2048: merge tiles; every 5 moves answer a question (wrong = a stone block) =====
let mg = null;
function mgNew(){ const g = Array.from({length:4}, () => Array(4).fill(0)); const m = { lesson, g, score:0, moves:0, phase:'play', q:null, opts:null, deck:shuffle(words()), msg:'', newCell:null, won:false, right:0 }; mgSpawn(m); mgSpawn(m); return m; }
function mgSpawn(m){ const e = []; m.g.forEach((r, y) => r.forEach((v, x) => { if (!v) e.push([y, x]); })); if (!e.length) return; const [y, x] = e[Math.floor(Math.random()*e.length)]; m.g[y][x] = Math.random() < 0.9 ? 2 : 4; m.newCell = y + ',' + x; }
function mgSlide(row){ const t = row.filter(v => v), out = []; let gain = 0;
  // stones (-1) split the row: tiles cannot pass or merge through them
  const segs = []; let cur = [];
  row.forEach(v => { if (v === -1){ segs.push(cur); segs.push(-1); cur = []; } else cur.push(v); }); segs.push(cur);
  segs.forEach(s => { if (s === -1){ out.push(-1); return; } const n = s.filter(v => v), r = []; for (let i = 0; i < n.length; i++){ if (n[i] === n[i+1]){ r.push(n[i]*2); gain += n[i]*2; i++; } else r.push(n[i]); } while (r.length < s.length) r.push(0); out.push(...r); });
  void t; return { row:out, gain }; }
function mgMove(m, d){
  const g = m.g, old = JSON.stringify(g); let gain = 0;
  for (let i = 0; i < 4; i++){
    let line = d === 'l' || d === 'r' ? g[i].slice() : g.map(r => r[i]);
    if (d === 'r' || d === 'd') line.reverse();
    const s = mgSlide(line); gain += s.gain; let nl = s.row; if (d === 'r' || d === 'd') nl = nl.reverse();
    if (d === 'l' || d === 'r') g[i] = nl; else nl.forEach((v, y) => g[y][i] = v);
  }
  if (JSON.stringify(g) === old) return false;
  m.score += gain; m.moves++; mgSpawn(m); return true;
}
function mgCanMove(m){ for (let y = 0; y < 4; y++) for (let x = 0; x < 4; x++){ const v = m.g[y][x]; if (!v) return true; if (v > 0 && ((x < 3 && m.g[y][x+1] === v) || (y < 3 && m.g[y+1][x] === v))) return true; } return false; }
function merge(){
  if (!mg || mg.lesson !== lesson) mg = mgNew();
  const best = load('2048:' + lesson, 0), S = $('#stage');
  if (mg.phase === 'over'){ if (mg.score > best) save('2048:' + lesson, mg.score);
    return endScreen('NO MORE MOVES', mg.score, Math.max(best, mg.score), `Biggest tile: ${Math.max(...mg.g.flat())} · ${mg.right} questions right.`, () => { mg = null; merge(); }); }
  const cells = mg.g.flat().map((v, i) => { const y = Math.floor(i/4), x = i % 4, nw = mg.newCell === y + ',' + x ? ' new' : '';
    return v === -1 ? `<div class="stone${nw}" aria-label="stone">stone</div>` : `<div class="${v ? (v > 2048 ? 'tbig' : 't' + v) : ''}${nw}">${v || ''}</div>`; }).join('');
  const panel = mg.phase === 'ask'
    ? `<div class="mode-tag">QUESTION TIME!</div><div class="def">${esc(mg.q[1])}</div><div class="opts" style="grid-template-columns:1fr 1fr">${mg.opts.map((o, i) => `<button data-i="${i}">${esc(o[0])}</button>`).join('')}</div><div class="hint" style="margin-top:10px">Right = +50 and a stone disappears. Wrong = a stone lands on the board.</div>`
    : `<div class="mode-tag">${mg.won ? 'YOU MADE 2048! KEEP GOING' : 'MERGE THE TILES'}</div><div class="hint">Next question in ${5 - (mg.moves % 5)} move${5 - (mg.moves % 5) === 1 ? '' : 's'}.</div><div class="hint">${esc(mg.msg)}</div>
       <div class="dpad" aria-label="Move buttons"><button class="u" data-d="u" aria-label="Up">▲</button><button class="l" data-d="l" aria-label="Left">◀</button><button class="d" data-d="d" aria-label="Down">▼</button><button class="r" data-d="r" aria-label="Right">▶</button></div>`;
  S.innerHTML = `<p class="how">2048 (solo): slide the tiles. Two equal tiles merge into one. Every 5 moves, answer a vocabulary question. Wrong answers drop grey stones that block your tiles!</p>
    <div class="stats"><span>Score: ${mg.score}</span><span>Moves: ${mg.moves}</span><span>Right answers: ${mg.right}</span><span>Best: ${best}</span></div>
    <div class="arc"><div class="g48" id="g48" aria-label="2048 board">${cells}</div><div class="panel top">${panel}</div></div>`;
  mg.newCell = null;
  if (mg.phase === 'ask'){
    S.querySelectorAll('.opts button').forEach(b => b.onclick = () => {
      const ok = mg.opts[+b.dataset.i] === mg.q;
      if (ok){ mg.right++; mg.score += 50; const st0 = []; mg.g.forEach((r, y) => r.forEach((v, x) => { if (v === -1) st0.push([y, x]); }));
        if (st0.length){ const [y, x] = st0[Math.floor(Math.random()*st0.length)]; mg.g[y][x] = 0; } mg.msg = 'Correct! +50'; }
      else { const e = []; mg.g.forEach((r, y) => r.forEach((v, x) => { if (!v) e.push([y, x]); })); if (e.length){ const [y, x] = e[Math.floor(Math.random()*e.length)]; mg.g[y][x] = -1; mg.newCell = y + ',' + x; } mg.msg = `Not quite: the word was “${mg.q[0]}”.`; }
      mg.phase = mgCanMove(mg) ? 'play' : 'over'; merge();
    });
    return;
  }
  const go = d => { if (mg.phase !== 'play') return; if (!mgMove(mg, d)) return;
    if (!mg.won && mg.g.flat().includes(2048)){ mg.won = true; mg.score += 500; }
    if (mg.moves % 5 === 0){ if (!mg.deck.length) mg.deck = shuffle(words()); mg.q = mg.deck.pop(); mg.opts = mcq(mg.q); mg.phase = 'ask'; }
    else if (!mgCanMove(mg)) mg.phase = 'over';
    mg.msg = ''; merge(); };
  mg.go = go;
  S.querySelectorAll('.dpad button').forEach(b => b.onclick = () => go(b.dataset.d));
  swipe($('#g48'), go);
}
document.addEventListener('keydown', e => {
  if (e.target && /^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName)) return;
  const k = {ArrowUp:'u', ArrowDown:'d', ArrowLeft:'l', ArrowRight:'r', w:'u', s:'d', a:'l', d:'r', W:'u', S:'d', A:'l', D:'r'}[e.key];
  if (mode === 'snake' && sn && sn.phase === 'play' && k && sn.turn){ e.preventDefault(); sn.turn(k); }
  else if (mode === 'merge' && mg && mg.phase === 'play' && k && mg.go){ e.preventDefault(); mg.go(k); }
  else if (mode === 'tower' && tw && tw.phase === 'swing' && (e.key === ' ' || e.key === 'Enter') && tw.drop){ e.preventDefault(); tw.drop(); }
});

document.addEventListener('keydown', e => { if (mode === 'blocks' && bk && bk.phase === 'place' && !bk.over && (e.key === 'r' || e.key === 'R')){ bk.piece = rot(bk.piece); blocks(); } });
document.addEventListener('visibilitychange', () => { if (document.hidden && mode === 'gravity' && gv && gv.phase === 'play'){ gv.pausedAt = performance.now(); } else if (!document.hidden && gv && gv.pausedAt){ gv.t0 += performance.now() - gv.pausedAt; gv.pausedAt = 0; } });
reset();
